/// <summary>
/// Service class for TMS engine processing.
/// </summary>
class METTMSEngineProcessingController extends SysOperationServiceController
{
}

Method.Source:
protected void new()
{
    super(classStr(METTMSEngineProcessingService), methodStr(METTMSEngineProcessingService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Defines caption.
/// </summary>
/// <returns>Caption</returns>
public ClassDescription defaultCaption()
{
    return "@MET:TMSEngineProcessing";
}

/// <summary>
/// Executes the batch job.
/// </summary>
/// <param name = "_args">
/// <c>Args</c>.
/// </param>
public static void main(Args _args)
{
    METTMSEngineProcessingController controller = new METTMSEngineProcessingController();
    controller.parmArgs(_args);
    controller.startOperation();
}
